using System.Security.Cryptography;
namespace FluxDrop.Core;
public static class SafeFiles {
 public const long MaxText=16*1024*1024;
 public static void Input(string path){if(!File.Exists(path)&&!Directory.Exists(path))throw new FileNotFoundException("El archivo se movió o no existe.");if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("No se admiten enlaces ni puntos de reanálisis.");}
 public static string SafeName(string name){if(string.IsNullOrWhiteSpace(name)||name is "." or ".."||name.IndexOfAny(Path.GetInvalidFileNameChars())>=0||name.IndexOfAny(['/', '\\', ':'])>=0||name.EndsWith('.')||name.EndsWith(' '))throw new IOException("Nombre de salida no válido.");var stem=name.Split('.')[0].ToUpperInvariant();if(new[]{"CON","PRN","AUX","NUL","COM1","COM2","COM3","COM4","COM5","COM6","COM7","COM8","COM9","LPT1","LPT2","LPT3","LPT4","LPT5","LPT6","LPT7","LPT8","LPT9"}.Contains(stem))throw new IOException("Nombre reservado de Windows.");return name;}
 public static void Space(string destination,long bytes){Directory.CreateDirectory(destination);Input(destination);var d=new DriveInfo(Path.GetPathRoot(Path.GetFullPath(destination))!);if(d.AvailableFreeSpace<Math.Max(bytes,16*1024*1024))throw new IOException("No hay espacio suficiente en el destino.");}
 public static string Publish(string temp,string destination,string name){SafeName(name);if(!File.Exists(temp)||new FileInfo(temp).Length==0)throw new IOException("El motor no produjo un archivo válido.");for(int i=0;i<10000;i++){string n=i==0?name:Path.GetFileNameWithoutExtension(name)+" ("+i+")"+Path.GetExtension(name);string target=Path.Combine(destination,n);try{File.Move(temp,target,false);return target;}catch(IOException)when(File.Exists(target)||Directory.Exists(target)) {}}throw new IOException("Demasiadas colisiones de nombres.");}
 public static string PublishDirectory(string temp,string destination,string name){SafeName(name);for(int i=0;i<10000;i++){string target=Path.Combine(destination,i==0?name:name+" ("+i+")");try{Directory.Move(temp,target);return target;}catch(IOException)when(File.Exists(target)||Directory.Exists(target)){}}throw new IOException("Demasiadas colisiones.");}
 public static async Task<string> Text(string path,CancellationToken token){Input(path);if(new FileInfo(path).Length>MaxText)throw new IOException("Texto demasiado grande: máximo 16 MB.");return await File.ReadAllTextAsync(path,new System.Text.UTF8Encoding(false,true),token);}
 public static IEnumerable<string> Walk(string path){Input(path);if(File.Exists(path)){yield return path;yield break;}foreach(var entry in Directory.EnumerateFileSystemEntries(path)){Input(entry);foreach(var file in Walk(entry))yield return file;}}
 public static async Task<string> Hash(string file,CancellationToken token){await using var s=File.OpenRead(file);return Convert.ToHexStringLower(await SHA256.HashDataAsync(s,token));}
 public static bool Within(string child,string parent){var p=Path.GetFullPath(parent).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;return Path.GetFullPath(child).StartsWith(p,OperatingSystem.IsWindows()?StringComparison.OrdinalIgnoreCase:StringComparison.Ordinal);}
 public static void ExtractName(string name){if(name.Length>240||name.StartsWith('/')||name.Contains('\\')||name.Contains(':')||name.Split('/').Any(n=>n==".."||n=="."))throw new IOException("Ruta insegura dentro del comprimido.");foreach(var p in name.TrimEnd('/').Split('/'))SafeName(p);}
 public static string Temp(string destination){Space(destination,0);var p=Path.Combine(destination,".fluxdrop-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(p);return p;}
}
